import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

export type SuggestedOrg = {
  id: number
  name: string
  primaryAvatarUrl: string
}

export type SessionData = {
  id: string
  status: string
  status_display: string
  status_icon: string
  title: string
  url?: string
  repository: {
    owner: string
    name: string
    full_name: string
  }
  started_at: string
  time_since_start: string
}

export type SessionsData = {
  sessions: SessionData[]
  pagination: {
    current_page: number
    total_pages: number
    total_count: number
    per_page: number
    has_previous: boolean
    has_next: boolean
  }
  heading: string
}

export function useSuggestedOrgs({slug, filter}: {slug: string; filter: string}) {
  const {data, isLoading, error} = useQuery({
    queryKey: ['copilot-agent-plane', 'suggested-orgs', slug, filter],
    queryFn: async () => {
      const url = new URL(
        `/enterprises/${slug}/ai-controls/agents/custom/source/org_suggestions`,
        window.location.origin,
      )
      if (filter) {
        url.searchParams.set('q', filter)
      }
      const response = await verifiedFetchJSON(url.toString())
      const json = await response.json()
      return json as SuggestedOrg[]
    },
  })

  return {data, isLoading, error}
}

export type ValidationResponse = {
  success: boolean
  reason?: string
  required_repository?: string
}

export async function setAndValidateOrgForCustomAgents({
  slug,
  organizationId,
}: {
  slug: string
  organizationId: number
}): Promise<ValidationResponse> {
  const response = await verifiedFetchJSON(
    `/enterprises/${slug}/ai-controls/agents/custom/source/organization?org_id=${organizationId}`,
    {
      method: 'PUT',
    },
  )
  const json = await response.json()
  return json as ValidationResponse
}

export async function unsetOrgForCustomAgents({slug}: {slug: string}): Promise<ValidationResponse> {
  const response = await verifiedFetchJSON(`/enterprises/${slug}/ai-controls/agents/custom/source/organization`, {
    method: 'DELETE',
  })
  // Handle 204 No Content response (no body to parse)
  if (response.status === 204) {
    return {success: true}
  }
  const json = await response.json()
  return json as ValidationResponse
}

export type CustomAgent = {
  name: string
  repo_owner: string
  repo_name: string
  url: string
}

export type CustomAgentsResponse = {
  custom_agents: CustomAgent[]
}

export async function fetchCustomAgents({slug}: {slug: string}): Promise<CustomAgentsResponse> {
  const response = await verifiedFetchJSON(`/enterprises/${slug}/ai-controls/agents/custom`)
  const json = await response.json()
  return json as CustomAgentsResponse
}

export async function toggleThirdPartyAgent({
  toggleUrl,
  enable,
}: {
  toggleUrl: string
  enable: boolean
}): Promise<boolean> {
  const response = await verifiedFetchJSON(toggleUrl, {
    method: 'PUT',
    body: {enable},
  })

  if (!response.ok) {
    throw new Error(`Failed to toggle agent.`)
  }

  return true
}

export default {
  useSuggestedOrgs,
  setAndValidateOrgForCustomAgents,
  unsetOrgForCustomAgents,
  fetchCustomAgents,
  toggleThirdPartyAgent,
}
