import {type PropsWithChildren, createContext, use, useMemo, useState} from 'react'
import type {Banner} from '../types'

export type PageBannerContext = {
  banner?: Banner
  clearBanner(): void
  setBanner(banner: Banner): void
}
export const PageBannerContext = createContext<PageBannerContext | undefined>(undefined)

export function PageBannerProvider({children}: PropsWithChildren) {
  const [currentBanner, setCurrentBanner] = useState<Banner | undefined>(undefined)
  const value = useMemo<PageBannerContext>(
    () => ({
      banner: currentBanner,
      clearBanner: () => setCurrentBanner(undefined),
      setBanner: (banner: Banner) => {
        setCurrentBanner(banner)
      },
    }),
    [currentBanner, setCurrentBanner],
  )
  return <PageBannerContext value={value}>{children}</PageBannerContext>
}

export function usePageBanner(): PageBannerContext {
  const context = use(PageBannerContext)
  if (!context) {
    throw new Error('usePageBanner must be used within a PageBannerProvider')
  }
  return context
}
