import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {sessionsRoute, type SessionsResponse} from './sessions-route'
import {ArrowLeftIcon, CodeIcon, CodeReviewIcon, LockIcon} from '@primer/octicons-react'
import {Link, PageHeader, Pagination, Stack} from '@primer/react'
import {Filter, FilterRevert} from '@github-ui/filter'
import {ControlGroup as ControlGroupNew} from '@github-ui/control-group'
import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useState, useMemo, useEffect, useCallback} from 'react'
import {getStatusIcon} from '../components/IconStatus'
import {useNavigate} from '@github-ui/use-navigate'
import {useLocation} from '@github-ui/react-router'
import {
  AgentFilterProvider,
  OrgFilterProvider,
  RepoFilterProvider,
  StatusFilterProvider,
  TimeframeFilterProvider,
  UserFilterProvider,
} from './sessions-filter-providers'
import type {FilterQuery} from '@github-ui/filter-core'

const SessionType = {
  CodingSession: 'coding_session',
  CodeReview: 'code_review',
  All: 'all',
} as const

const getCategoryLabel = (category?: string): {label: string; icon: React.ReactNode} | null => {
  if (category === SessionType.CodingSession) {
    return {label: 'Coding Agent', icon: <CodeIcon size={12} />}
  }
  if (category === SessionType.CodeReview) {
    return {label: 'Code Review', icon: <CodeReviewIcon size={12} />}
  }
  return null
}

export function Sessions() {
  const {data: payload} = useRouteQuery(sessionsRoute, 'mainQuery')
  return <PrimerFilter payload={payload} />
}

export function PrimerFilter({payload}: {payload: SessionsResponse}) {
  const controlGroupUnificationEnabled = isFeatureEnabled('control-group-unification')
  const ControlGroup = controlGroupUnificationEnabled ? ControlGroupNew : EnterpriseControlGroup

  const location = useLocation()
  const navigate = useNavigate()
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const no_access_label_enabled = useFeatureFlag('agent_sessions_no_access_label')

  // Parse URL query params - recalculate when location changes
  // Default to timeframe:24h when no query is present
  const initialQuery = useMemo(() => {
    const urlParams = new URLSearchParams(location.search)
    const query = urlParams.get('query')
    if (query) return query
    return 'timeframe:24h'
  }, [location.search])

  // Filter state management (matches SecurityCenter pattern)
  const [filterValue, setFilterValue] = useState(initialQuery)
  const [submittedQuery, setSubmittedQuery] = useState(initialQuery)

  // Sync filter state when URL changes (e.g., browser back/forward, manual URL edit)
  useEffect(() => {
    setFilterValue(initialQuery)
    setSubmittedQuery(initialQuery)
  }, [initialQuery])

  // Set default timeframe:24h in URL when no query is present
  useEffect(() => {
    const urlParams = new URLSearchParams(location.search)
    if (!urlParams.get('query')) {
      const params = new URLSearchParams(location.search)
      params.set('query', 'timeframe:24h')
      navigate(`${location.pathname}?${params.toString()}`, {replace: true})
    }
  }, [location.pathname, location.search, navigate])

  // Create filter providers - agent options from API, org and repo filters fetch suggestions from API
  const filterProviders = useMemo(() => {
    const orgSuggestionsUrl = `${location.pathname}/organizations/suggestions`
    const repoSuggestionsUrl = `${location.pathname}/repositories/suggestions`
    const userSuggestionsUrl = `${location.pathname}/users/suggestions`
    return [
      new StatusFilterProvider(payload.status_display_names ?? []),
      new TimeframeFilterProvider(payload.timeframe_filters ?? []),
      new AgentFilterProvider(payload.agent_filters ?? []),
      new OrgFilterProvider(orgSuggestionsUrl),
      new RepoFilterProvider(repoSuggestionsUrl),
      new UserFilterProvider(userSuggestionsUrl),
    ]
  }, [location.pathname, payload.agent_filters, payload.timeframe_filters, payload.status_display_names])

  // Update URL and trigger refetch
  const updateUrlParams = useCallback(
    (query: string, page: number) => {
      const params = new URLSearchParams(location.search)

      if (query) {
        params.set('query', query)
      } else {
        params.delete('query')
      }

      if (page > 1) {
        params.set('page', page.toString())
      } else {
        params.delete('page')
      }

      const newUrl = `${location.pathname}?${params.toString()}`
      navigate(newUrl)
    },
    [location.pathname, location.search, navigate],
  )

  const defaultTimeframeQuery = 'timeframe:24h'

  // Handle filter changes (typing in the input)
  const handleFilterChange = (newValue: string) => {
    setFilterValue(newValue)
  }

  // Handle filter submission (Enter key or explicit submit)
  // Ensure timeframe filter is always present
  const handleFilterSubmit = useCallback(
    (request: FilterQuery) => {
      let newQuery = request.raw.trim()
      if (!newQuery.includes('timeframe:')) {
        newQuery = newQuery ? `${defaultTimeframeQuery} ${newQuery}` : defaultTimeframeQuery
      }
      setFilterValue(newQuery)
      setSubmittedQuery(newQuery)
      updateUrlParams(newQuery, 1)
    },
    [updateUrlParams],
  )

  // Handle filter revert - reset to default timeframe
  const handleRevert = useCallback(() => {
    setFilterValue(defaultTimeframeQuery)
    setSubmittedQuery(defaultTimeframeQuery)
    updateUrlParams(defaultTimeframeQuery, 1)
  }, [updateUrlParams])

  // Check if filtered beyond the default timeframe
  const isFiltered = submittedQuery !== defaultTimeframeQuery
  const sessions = payload.sessions
  const {current_page, total_pages, total_count} = payload.pagination

  const handlePageChange = useCallback(
    (e: React.MouseEvent | React.KeyboardEvent, page: number) => {
      e.preventDefault()
      updateUrlParams(submittedQuery, page)
    },
    [submittedQuery, updateUrlParams],
  )

  return (
    <Stack>
      <Link href="..">
        <ArrowLeftIcon /> Agents
      </Link>

      <PageHeader>
        <PageHeader.TitleArea>
          <PageHeader.Title as="h2">Agent sessions</PageHeader.Title>
        </PageHeader.TitleArea>
      </PageHeader>

      <div className="tmp-mb-3">
        <Filter
          data-testid="sessions-filter"
          id="sessions-filter"
          label="Filter sessions"
          variant="input"
          providers={filterProviders}
          filterValue={filterValue}
          onChange={handleFilterChange}
          onSubmit={handleFilterSubmit}
        />
        {isFiltered && (
          <div className="mt-2">
            <FilterRevert as="button" onClick={handleRevert} />
          </div>
        )}
      </div>

      <Stack>
        {sessions.length === 0 ? (
          <div className="Box-row tmp-py-6 text-center fgColor-muted">
            {total_count === 0 && !isFiltered ? 'No agent sessions found.' : 'No sessions match your filters.'}
          </div>
        ) : (
          <>
            <ControlGroup>
              {sessions.map(session => {
                const isInaccessible = no_access_label_enabled && session.accessible === false

                return (
                  <ControlGroup.Item
                    key={session.id}
                    leadingVisual={
                      <div style={{paddingLeft: '2px', paddingTop: '1px'}}>{getStatusIcon(session.status)}</div>
                    }
                  >
                    <ControlGroup.Title>
                      {isInaccessible ? (
                        <span className="d-inline-flex flex-items-center gap-1 fgColor-muted">
                          {session.title}
                          <LockIcon size={16} className="ml-1" />
                        </span>
                      ) : session.url ? (
                        <Link href={session.url} className="Link--primary no-underline">
                          {session.title}
                        </Link>
                      ) : (
                        <span>{session.title}</span>
                      )}
                    </ControlGroup.Title>
                    <ControlGroup.Description>
                      <div className="text-small fgColor-muted">
                        {session.agent && (
                          <>
                            {(() => {
                              const categoryInfo = getCategoryLabel(session.agent.category)
                              return categoryInfo ? (
                                <span className="d-inline-flex flex-items-center gap-1">
                                  {categoryInfo.icon}
                                  <span>{categoryInfo.label}</span>
                                </span>
                              ) : (
                                <span>{session.agent.name}</span>
                              )
                            })()}
                            <span className="mx-1">·</span>
                          </>
                        )}
                        <Link href={`/${session.repository.full_name}`} className="Link--muted">
                          {session.repository.full_name}
                        </Link>
                        <span className="mx-1">·</span>
                        <span>Started {session.time_since_start}</span>
                      </div>
                    </ControlGroup.Description>
                    <ControlGroup.Custom>
                      <div className="d-flex flex-row flex-items-center gap-2">
                        <span className="text-small">{session.status_display}</span>
                      </div>
                    </ControlGroup.Custom>
                  </ControlGroup.Item>
                )
              })}
            </ControlGroup>
            {no_access_label_enabled && (
              <div className="tmp-mt-3 d-flex flex-items-center gap-2 text-small fgColor-muted">
                <LockIcon size={12} className="flex-shrink-0" />
                <span>
                  Indicates that you do not have access to view all content in this repository. To view code, pull
                  requests, and other content as an enterprise owner, enable temporary access{' '}
                  <Link
                    inline
                    href="https://docs.github.com/en/enterprise-cloud@latest/admin/managing-accounts-and-repositories/managing-repositories-in-your-enterprise/accessing-user-owned-repositories-in-your-enterprise"
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    here
                  </Link>
                  .
                </span>
              </div>
            )}
            {total_pages > 1 && (
              <Pagination
                pageCount={total_pages}
                currentPage={current_page}
                onPageChange={handlePageChange}
                showPages
                surroundingPageCount={2}
              />
            )}
          </>
        )}
      </Stack>
    </Stack>
  )
}
