import {ControlGroup as ControlGroupNew} from '@github-ui/control-group'
import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {TriangleDownIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'

export const ThirdPartyAgentMode = {
  allowed: 'allowed',
  disabled: 'disabled',
} as const
export type ThirdPartyAgentMode = (typeof ThirdPartyAgentMode)[keyof typeof ThirdPartyAgentMode]

const EXPANDED_NAMES = new Map<string, string>([
  ['Claude', 'Anthropic Claude'],
  ['Codex', 'OpenAI Codex'],
])

const AGENT_DOC_URLS = new Map<string, string>([
  ['Claude', 'https://docs.github.com/en/copilot/concepts/agents/about-third-party-agents'],
  ['Codex', 'https://docs.github.com/en/copilot/concepts/agents/about-third-party-agents'],
])

const MODE_OPTIONS = [
  {
    name: ThirdPartyAgentMode.disabled,
    label: 'Disabled',
    description: 'This agent cannot be installed by any organizations.',
  },
  {
    name: ThirdPartyAgentMode.allowed,
    label: 'Allowed',
    description: 'This agent can be installed by organizations.',
  },
]

type Integration = {
  avatarUrl: string
}

export type ThirdPartyAgent = {
  name: string
  mode: ThirdPartyAgentMode
  docUrl: string
  toggleUrl: string
  integration: Integration
}

function agentNameWithExpansion(agent: ThirdPartyAgent) {
  return EXPANDED_NAMES.get(agent.name) || agent.name
}

function agentDescription(agent: ThirdPartyAgent) {
  const docUrl = AGENT_DOC_URLS.get(agent.name) ?? agent.docUrl
  return (
    <>
      <a href={docUrl} target="_blank" rel="noopener noreferrer">
        Learn more about {agent.name} agent on GitHub
      </a>
    </>
  )
}

function customLeadingVisual(agent: ThirdPartyAgent) {
  return (
    <div style={{alignSelf: 'center'}}>
      <GitHubAvatar square size={34} src={agent.integration.avatarUrl} alt={`${agent.name} avatar`} />
    </div>
  )
}

const getLabel = (mode: ThirdPartyAgentMode) => (mode === ThirdPartyAgentMode.allowed ? 'Allowed' : 'Disabled')

export type ThirdPartyAgentSelectorProps = {
  agent: ThirdPartyAgent
  canModify: boolean
  currentMode: ThirdPartyAgentMode
  onModeChange?(mode: string): void
}

export function ThirdPartyAgentSelector({agent, canModify, currentMode, onModeChange}: ThirdPartyAgentSelectorProps) {
  const controlGroupUnificationEnabled = isFeatureEnabled('control-group-unification')
  const ControlGroup = controlGroupUnificationEnabled ? ControlGroupNew : EnterpriseControlGroup

  const leadingVisual = customLeadingVisual(agent)

  if (!canModify) {
    return (
      <ControlGroup.Item leadingVisual={leadingVisual} key={agent.name}>
        <ControlGroup.Title>{agentNameWithExpansion(agent)}</ControlGroup.Title>
        <ControlGroup.Description>{agentDescription(agent)}</ControlGroup.Description>
        <ControlGroup.Custom>
          <Button inactive trailingAction={TriangleDownIcon}>
            {getLabel(currentMode)}
          </Button>
        </ControlGroup.Custom>
      </ControlGroup.Item>
    )
  }

  return (
    <ControlGroup.Selector
      leadingVisual={leadingVisual}
      key={agent.name}
      title={agentNameWithExpansion(agent)}
      description={agentDescription(agent)}
      selectedMode={currentMode}
      onModeChange={onModeChange}
      modes={MODE_OPTIONS}
    />
  )
}
