import {useSlots} from '@primer/react/experimental'
import Title from './Title'
import Description from './Description'
import {Button, InlineEdit, ToggleSwitch, Custom} from './Controls'
import {Link} from '@primer/react'
import LinkLabel from './LinkLabel'
import styled from 'styled-components'
import styles from './Item.module.css'
import {clsx} from 'clsx'
import {ChevronRightIcon} from '@primer/octicons-react'
import Footer from './Footer'

export type ControlGroupItemProps = {
  children: React.ReactNode
  nestedLevel?: 0 | 1 | 2
  disabled?: boolean
  contentsClassname?: string
  leadingIcon?: React.ReactNode
  href?: string
  linkLabel?: string | React.ReactNode
  leadingVisual?: React.ReactNode
}

const slotConfig = {
  title: Title,
  description: Description,
  custom: Custom,
  toggle: ToggleSwitch,
  button: Button,
  inlineEdit: InlineEdit,
  linkLabel: LinkLabel,
  footer: Footer,
}

const StyledLink = styled(Link)`
  text-decoration: none;
  color: inherit;
  :hover {
    text-decoration: none;
  }
  ::after {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    top: 0;
    content: '';
  }
  :focus {
    text-decoration: underline;
    outline: none;
  }
  :visited {
    color: inherit;
  }
`

const Item = ({
  children,
  nestedLevel = 0,
  disabled = false,
  contentsClassname,
  leadingIcon = null,
  leadingVisual = null,
  href,
}: ControlGroupItemProps) => {
  const [{title, description, custom, toggle, button, inlineEdit, linkLabel, footer}] = useSlots(children, slotConfig)
  const blockControl = button || inlineEdit || custom || toggle || linkLabel

  return (
    <>
      <div
        className={clsx(
          'controlBoxContainer',
          styles.container,
          disabled && styles.disabled,
          href && styles['link'],
          href && !blockControl && styles.linkWithoutControl,
        )}
        style={{'--nested-level': nestedLevel}}
        data-nested-level={nestedLevel}
      >
        <div className={clsx(styles.contents, contentsClassname)}>
          {leadingIcon || leadingVisual ? (
            leadingVisual ? (
              <div className={styles.leadingVisual}>{leadingVisual}</div>
            ) : (
              <div className={`${styles.leadingVisual} ${styles.blockIcon}`}>
                <div className={styles.leadingIcon}>{leadingIcon}</div>
              </div>
            )
          ) : null}
          {href && title ? (
            <StyledLink href={href} className={styles.title}>
              {title}
            </StyledLink>
          ) : (
            title && <div className={clsx(styles.title, 'titleBox')}>{title}</div>
          )}
          {description && <div className={clsx(styles.description, 'descriptionBox')}>{description}</div>}
          {blockControl && <div className={clsx(styles.blockControl, 'blockControl')}>{blockControl}</div>}
          {href && !blockControl ? (
            <div className={clsx(styles.blockControl)}>
              <span className="d-flex fgColor-muted flex-items-center align-self-center height-full flex-justify-center">
                <ChevronRightIcon />
              </span>
            </div>
          ) : undefined}
        </div>
      </div>
      {footer && <div className={clsx(styles.footer, 'footer')}>{footer}</div>}
    </>
  )
}

export default Item
